import numpy as np

def feature(current, candidates, tour, start):
    """Cosine alignment of the outgoing leg with the incoming leg, gated to the first half of the decisions."""
    k = candidates.shape[0]
    m = tour.shape[0]
    if k <= 1 or m < 2:
        return np.zeros(k)
    frac = m / (m + k - 1)
    gate = max(0.0, 1.0 - 2.0 * frac)
    if gate == 0.0:
        return np.zeros(k)
    incoming = current - tour[-2]
    norm_in = np.linalg.norm(incoming)
    if norm_in < 1e-12:
        return np.zeros(k)
    u = incoming / norm_in
    outgoing = candidates - current
    norm_out = np.linalg.norm(outgoing, axis=1)
    cos = (outgoing @ u) / np.maximum(norm_out, 1e-9)
    return gate * cos
```

This computes, for each candidate, the cosine of the angle between the incoming leg (previous city to current) and the outgoing leg (current to candidate), multiplied by a linear gate that is 1 at the first decision and 0 from the halfway point onward; it returns zeros when there are fewer than two candidates, fewer than two visited cities, a degenerate incoming leg, or a zero gate.

